const body = $input.first().json.body || $input.first().json || {};

const userMessage = body.message || body.query || body.prompt || body.chatInput || "";
const repoUrl = body.repoUrl || body.repository || body.url || "";
const contextData = body.context || body.summary || body.analysis || {};
const history = Array.isArray(body.history) ? body.history.slice(-6) : [];

let repoName = body.repoName || body.name || body.full_name || body.fullName || "";

if (!repoName && repoUrl) {
  repoName = repoUrl.split('/').slice(-2).join('/').replace(/\.git$/, '');
}

const contextStr = typeof contextData === 'object' ? JSON.stringify(contextData) : String(contextData);

if (!repoName && contextStr) {
  const match = contextStr.match(/([a-zA-Z0-9_\-]+\/[a-zA-Z0-9_\-]+)/);
  if (match) {
    repoName = match[1].trim();
  }
}

const finalRepoName = repoName || "sirpi-in/csr-n8n-frontend";

let historyStr = "";
if (history.length > 0) {
  historyStr = "\nRECENT CONVERSATION HISTORY:\n" + history.map(h => `${h.role === 'user' ? 'User' : 'Assistant'}: ${h.content}`).join("\n");
}

return [{
  json: {
    userMessage,
    repoUrl,
    repoName: finalRepoName,
    contextStr,
    historyStr
  }
}];

function getVector(text) {
  const vec = new Array(768).fill(0);
  const words = String(text || '').toLowerCase().match(/[a-z0-9_$]+/g) || [];
  if (words.length === 0) return vec;

  for (const word of words) {
    let hash = 5381;
    for (let i = 0; i < word.length; i++) {
      hash = ((hash << 5) + hash) + word.charCodeAt(i);
      hash = hash & hash;
    }
    const idx = Math.abs(hash) % 768;
    vec[idx] += 1;
  }

  let norm = Math.sqrt(vec.reduce((sum, v) => sum + v * v, 0));
  if (norm === 0) norm = 1;
  return vec.map(v => Number((v / norm).toFixed(6)));
}

const input = $input.first().json || {};
const userMessage = input.userMessage || '';
const embedding = getVector(userMessage);

return [{
