const input = $input.first().json || {};
const chunks = input.chunks || [];
const userMessage = input.userMessage || "";
const repoName = input.repoName || "this repository";
const repoUrl = input.repoUrl || "";
const contextStr = input.contextStr || "";
const historyStr = input.historyStr || "";

let prompt = "";
let citedFiles = [];

if (chunks.length > 0) {
  const contextBlock = chunks
    .slice(0, 5)
    .map(c => `FILE: ${c.file_path}\n${String(c.chunk_text || '').slice(0, 2000)}`)
    .join('\n\n');

  citedFiles = [...new Set(chunks.map(c => c.file_path).filter(Boolean))].slice(0, 5);

  prompt = `You are GitGrok Chat, an expert AI assistant answering questions about the repository "${repoName}".

RELEVANT SOURCE CODE CHUNKS:
${contextBlock}

REPOSITORY METADATA:
- Name: ${repoName}
- URL: ${repoUrl}
${historyStr}

USER QUESTION:
${userMessage}

INSTRUCTIONS:
1. Answer accurately and specifically.
2. Do NOT use markdown bold asterisks (**) or triple asterisks (***).
3. If asked for the repository name or project name, explicitly state "${repoName}".
4. Reference exact file paths for code claims.`;
} else {
  prompt = `You are GitGrok Chat, an expert AI assistant answering questions about software repositories.

TARGET REPOSITORY DETAILS:
- Name: ${repoName}
- URL: ${repoUrl}
${contextStr ? `- Overview Context: ${contextStr}` : ''}
${historyStr}

USER QUESTION:
${userMessage}

INSTRUCTIONS:
1. Do NOT use markdown bold asterisks (**) or triple asterisks (***).
2. If the user asks for the repository name or project name, explicitly state "${repoName}".
3. Answer the question using the repository details provided above.
4. Keep responses concise, clear, and helpful.`;
}

return [{
  json: {
    prompt,
    citedFiles,
    notIndexed: chunks.length === 0
  }
}];

